   300→  /**
   301→   * This class can be used by multiple threads, so this function should be thread-safe to avoid extra
   302→   * script compilation.
   303→   */
   304→  @EnsuresNonNull("compiledScript")
   305→  private JavaScriptAggregator.ScriptAggregator getCompiledScript()
   306→  {
   307→    // JavaScript configuration should be checked when it's actually used because someone might still want Druid
   308→    // nodes to be able to deserialize JavaScript-based objects even though JavaScript is disabled.
   309→    Preconditions.checkState(config.isEnabled(), "JavaScript is disabled");
   310→
   311→    JavaScriptAggregator.ScriptAggregator syncedCompiledScript = compiledScript;
   312→    if (syncedCompiledScript == null) {
   313→      synchronized (config) {
   314→        syncedCompiledScript = compiledScript;
   315→        if (syncedCompiledScript == null) {
   316→          syncedCompiledScript = compileScript(fnAggregate, fnReset, fnCombine);
   317→          compiledScript = syncedCompiledScript;
   318→        }
   319→      }
   320→    }
   321→    return syncedCompiledScript;
   322→  }
   323→
   324→  @VisibleForTesting
   325→  static JavaScriptAggregator.ScriptAggregator compileScript(
   326→      final String aggregate,
   327→      final String reset,
   328→      final String combine
   329→  )
   330→  {
   331→    final ContextFactory contextFactory = ContextFactory.getGlobal();
   332→    Context context = contextFactory.enterContext();
   333→    context.setOptimizationLevel(JavaScriptConfig.DEFAULT_OPTIMIZATION_LEVEL);
   334→
   335→    final ScriptableObject scope = context.initStandardObjects();
   336→
   337→    final Function fnAggregate = context.compileFunction(scope, aggregate, "aggregate", 1, null);
   338→    final Function fnReset = context.compileFunction(scope, reset, "reset", 1, null);
   339→    final Function fnCombine = context.compileFunction(scope, combine, "combine", 1, null);
   340→    Context.exit();
   341→
   342→    return new JavaScriptAggregator.ScriptAggregator()
   343→    {
   344→      @Override
   345→      public double aggregate(final double current, final BaseObjectColumnValueSelector[] selectorList)
   346→      {
   347→        Context cx = Context.getCurrentContext();
   348→        if (cx == null) {
   349→          cx = contextFactory.enterContext();
   350→
   351→          // Disable primitive wrapping- we want Java strings and primitives to behave like JS entities.
   352→          cx.getWrapFactory().setJavaPrimitiveWrap(false);
   353→        }
   354→
   355→        final int size = selectorList.length;
   356→        final Object[] args = new Object[size + 1];
   357→
   358→        args[0] = current;
   359→        for (int i = 0; i < size; i++) {
   360→          final BaseObjectColumnValueSelector selector = selectorList[i];
   361→          if (selector != null) {
   362→            final Object arg = selector.getObject();
   363→            if (arg != null && arg.getClass().isArray()) {
   364→              // Context.javaToJS on an array sort of works, although it returns false for Array.isArray(...) and
   365→              // may have other issues too. Let's just copy the array and wrap that.
   366→              args[i + 1] = cx.newArray(scope, arrayToObjectArray(arg));
   367→            } else if (arg instanceof List) {
   368→              // Using toArray(Object[]), instead of just toArray(), because Arrays.asList()'s impl and similar List
   369→              // impls could clone the underlying array in toArray(), that could be not Object[], but e. g. String[].
   370→              args[i + 1] = cx.newArray(scope, ((List) arg).toArray(ObjectArrays.EMPTY_ARRAY));
   371→            } else {
   372→              args[i + 1] = Context.javaToJS(arg, scope);
   373→            }
   374→          }
   375→        }
   376→
   377→        final Object res = fnAggregate.call(cx, scope, scope, args);
   378→        return Context.toNumber(res);
   379→      }
   380→
   381→      private Object[] arrayToObjectArray(Object array)
   382→      {
   383→        int len = Array.getLength(array);
   384→        final Object[] objectArray = new Object[len];
   385→        for (int j = 0; j < len; j++) {
   386→          objectArray[j] = Array.get(array, j);
   387→        }
   388→        return objectArray;
   389→      }
   390→
   391→      @Override
   392→      public double combine(final double a, final double b)
   393→      {
   394→        final Object res = contextFactory.call(
   395→            new ContextAction()
   396→            {
   397→              @Override
   398→              public Object run(final Context cx)
   399→              {
   400→                return fnCombine.call(cx, scope, scope, new Object[]{a, b});
   401→              }
   402→            }
   403→        );
   404→        return Context.toNumber(res);
   405→      }
   406→
   407→      @Override
   408→      public double reset()
   409→      {
   410→        final Object res = contextFactory.call(
   411→            new ContextAction()
   412→            {
   413→              @Override
   414→              public Object run(final Context cx)
   415→              {
   416→                return fnReset.call(cx, scope, scope, new Object[]{});
   417→              }
   418→            }
   419→        );
   420→        return Context.toNumber(res);
   421→      }
   422→
   423→      @Override
   424→      public void close()
   425→      {
   426→        if (Context.getCurrentContext() != null) {
   427→          Context.exit();
   428→        }
   429→      }
   430→    };
